// Generated by bundle-improver.mjs.
export const AUTHORED_IMPROVER = {
  "componentSearchStep/rewriteComponents.nl": "---\nkind: directory-reducer\nargs:\n  request: ComponentRewriteRequest\nreturns: Candidate\n---\nImprove the selected instruction components using the supplied training feedback. This is a typed edit of the component source folder.\n\nRead components.json. Each value is either {kind:'program.guidance',text:string} or {kind:'lambda.instructions',template:{segments:string[],slotIds:string[]}}. Edit only request.keys. Keep every kind, slotIds, unselected component, and the number of segments unchanged. Static segments are ordinary string arrays: do not encode an array as a string. Preserve the behavior expected by the examples and immutable component contracts. request.feedback is a pageable read-only view: inspect request.feedback.length and request.feedback.page(start, limit) (at most 200 records per page). Select useful evidence without discarding the rest. Use it to identify a specific failure and repair its instructions concisely.\n\nWrite the complete revised candidate to components.json, then return that exact object with `return candidate;` in an eval. Do not merely inspect it. The returned value and edited file must agree.\n",
  "componentSearchStep.nl": "---\nkind: directory-reducer\nargs:\n  state: ComponentLoopState\nreturns: ComponentLoopState\n---\nPerform one component-search experiment and return the next joint source/state checkpoint. You own experiment sequencing. The search service supplies exact GEPA selection math, declared dependencies, independent evaluation and checked state assembly; it never runs a search loop.\n\nCall search.plan(state.iteration). This draws the seeded per-case frontier parent and dependency update group, charges one experiment, and supplies the parent's typed component values plus complete training feedback. If stopReason is coverage-gap, finish with that stop reason and no acceptance. Otherwise install plan.parent in folder's components.json before proposing edits.\n\nWhen plan.compose is true, call search.merge() for conservative three-way composition. A conflict gives null; then use a normal proposal. For a normal proposal, call folder.propose(rewriteComponents, {keys:plan.keys,components:plan.components,feedback:plan.feedback}). The returned value must equal the edited components.json. The rewrite child can page feedback rather than receiving a truncated first dozen examples.\n\nCall search.check(candidate). A rejected check finishes this experiment with accepted:false and concrete diagnostics. Duplicates in plan.duplicateIds finish without evaluation or acceptance. For a new valid candidate, evaluate both parent and candidate on the same minibatch using search.evaluate(id,'mini',true) and search.evaluate(id,'mini'). Accept only when candidate gates pass and its quality strictly exceeds the parent's. A rejection still records a completed experiment. For an accepted candidate, explicitly evaluate full training and validation using search.evaluate(id,'train') and search.evaluate(id,'validation'); pass their evidence references to search.finish.\n\nsearch.finish({candidate:id,accepted,train:training.evidence,validation:validated.evidence}) verifies exact acceptance, applies validation constraints and guidance coverage, protects the baseline/incumbent while pruning the per-case frontier, and returns {state,candidate}. It does not choose semantic edits. For an invalid proposal use {accepted:false,error:reason}. Never catch exhaustion or cancellation to create more capacity. The state iteration advances exactly once for each charged experiment.\n\nFinally write returned candidate to folder.file('components.json') and explicitly `return finished.state;` from eval. The selected source can differ from the proposed child: preserve that distinction. Test evidence is absent and cannot drive this experiment. Do not fabricate metrics or ask for a host optimizer endpoint. Reply done after returning the completed typed state.\n",
  "counterexampleStep/suggestCounterexamples.nl": "---\nargs:\n  goal: string\n  evidence: unknown[]\nreturns: unknown[][]\n---\nPropose at most four new argument lists exposing a missing boundary or interaction in the intended behavior. Use the goal and observed training failures. Return inputs only. Expected outcomes belong to the independent oracle. Do not request evaluation, read protected cases, or invent gold.\n",
  "counterexampleStep.nl": "---\nkind: directory-reducer\nargs:\n  state: CounterexampleState\n  goal: string\nreturns: CounterexampleState\n---\nPerform one counterexample-guided repair experiment. The suite's expected outcomes belong to an independent author-provided oracle. Never supply or alter gold yourself.\n\nRead folder.snapshot() and ask counterexamples.evidence for its training failures. Call suggestCounterexamples with goal and that evidence to propose inputs exposing a missing behavior. Ask counterexamples.admit to check those inputs against the independent oracle. It returns the new suite identity, admitted count and remaining check allowance; validation and test cases remain pinned. If none were admitted, retain source and stop with an honest reason.\n\nIf examples were admitted, call counterexamples.repair(folder.snapshot()) to run the ordinary authored improvement program on the new suite. Install its actual returned source with await folder.select(result.folder), and record its disposition and measured quality. Stop when the repaired training suite passes, checks are exhausted, or this experiment failed to produce a completed eligible repair. Increment state.round exactly once. Return the typed next state with the actual suite identity, remaining checks, quality, done and reason. Never invent additional capacity or evaluate a target yourself.\n",
  "improveStep/baseline.ts": "import type {SearchState} from '../types';\ntype MeasuredSource = {source:string;quality:number;sourceBytes?:number;modelCalls?:number;scores?:{caseId:string;quality:number}[]};\n/** Assemble baseline state without asking the model to reproduce its schema. */\nexport function start(state:SearchState,baseline:MeasuredSource):SearchState {\n  return {...state,incumbent:baseline.source,quality:baseline.quality,population:[{source:baseline.source,quality:baseline.quality,parent:'',...(baseline.sourceBytes!==undefined?{cost:baseline.sourceBytes}:{}),...(baseline.modelCalls!==undefined?{modelCalls:baseline.modelCalls}:{}),...(baseline.scores?{scores:baseline.scores}:{})}]};\n}\n",
  "improveStep/capabilities.ts": "import type {RewriteRequest,TrainingEvidence} from '../types';\n\ntype Measurement={source:string;quality:number;sourceBytes:number;modelCalls?:number;gatesPassed:boolean;evidence:string;scores?:{caseId:string;quality:number}[]};\ntype Proposal={folder:Snapshot;value:{summary:string};diff:{changes:unknown[]}};\nexport type Snapshot={digest:string;filePaths():string[];readText(path:string):Promise<string>;branch():Draft};\ntype Draft={filePaths():string[];readText(path:string):Promise<string>;propose(reducer:unknown,request:RewriteRequest):Promise<Proposal>;accept(proposal:Proposal):Promise<Snapshot>};\nexport type ExperimentFolder={at(source:string):Snapshot};\nexport type ExperimentEvaluator={evaluate(source:Snapshot,request:{split:'train'|'validation';seed:number}):Promise<Measurement>;page(reference:string):TrainingEvidence[];check(source:Snapshot):Promise<{valid:boolean;diagnostics:string[]}>};\n",
  "improveStep/context.ts": "import type {ImprovementPolicy,RewriteRequest,TrainingEvidence,SourceFile,ExperimentOutcome} from '../types';\n\n/** Pass the actual training evidence through unchanged; the model chooses only its hypothesis. */\nexport function request(policy:ImprovementPolicy,hypothesis:string,evidence:unknown[],sourceFiles:SourceFile[],history:ExperimentOutcome[]=[],lastExperiment?:unknown):RewriteRequest {\n  return {history,...(lastExperiment?{lastExperiment}:{}),brief:brief(policy,evidence as TrainingEvidence[],sourceFiles,hypothesis),objective:policy.objective??'quality',goal:policy.goal,mode:policy.mode,hypothesis,sourceFiles,evidence,allowedFiles:policy.allowedFiles};\n}\n\n/** A small first read; complete source and observations remain available in the typed context. */\nexport function brief(policy:ImprovementPolicy,evidence:TrainingEvidence[],sourceFiles:SourceFile[],hypothesis:string=''):string {\n  const lines=['Goal: '+policy.goal,'Mode: '+policy.mode+'; objective: '+(policy.objective??'quality'),'Allowed edits: '+policy.allowedFiles.join(', ')];\n  if(hypothesis)lines.push('Hypothesis: '+hypothesis);\n  for(const file of sourceFiles)lines.push('Source '+file.path+':\\n'+file.text.slice(0,1200)+(file.text.length>1200?'\\n[clipped; full text in sourceFiles]':''));\n  for(const row of evidence){\n    lines.push('Training '+(row.caseId??'case')+': '+(row.passed?'passed':'failed')+'; model requests '+(row.modelCalls??'unknown')+(row.failureKind?'; '+row.failureKind:'')+(row.error?'; '+row.error.slice(0,400):''));\n    if(!row.passed)lines.push('Observed: '+JSON.stringify({args:row.args,value:row.value,expected:row.expected}).slice(0,700));\n    for(const step of row.modelTrace??[]){\n      const calls=step.calls as {name:string;arguments?:Record<string,unknown>}[];\n      lines.push('Action: '+calls.map(call=>call.name+' '+JSON.stringify(call.arguments??{}).slice(0,220)).join('; '));\n      if(/error|rejected|failed/i.test(step.observation))lines.push('Tool observation: '+step.observation.slice(0,400));\n    }\n  }\n  const result=lines.join('\\n');\n  return result.slice(0,6000)+(result.length>6000?'\\n[card clipped; inspect the implicated sourceFiles or evidence field]':'');\n}\n\n/** Identify an evidenced objective; the model still decides which change can help. */\nexport function opportunity(policy:ImprovementPolicy,evidence:TrainingEvidence[]):{kind:'fixture'|'quality'|'efficiency'|'source-size'|'none';reason:string} {\n  if(evidence.some(row=>row.failureKind==='fixture'))return {kind:'fixture',reason:'Independent fixture failed before target execution.'};\n  if(evidence.some(row=>!row.passed))return {kind:'quality',reason:'A current target execution failed; diagnose its actual outcome and trace.'};\n  if(policy.objective==='model-calls'&&evidence.some(row=>row.modelCalls!==undefined&&row.modelCalls>1))return {kind:'efficiency',reason:'Correct answers still took multiple model requests. Inspect the trace for avoidable inspection, repair, delegation or a separate completion request. Passing quality does not complete the cost objective.'};\n  if(policy.objective==='source-size')return {kind:'source-size',reason:'Correct answers permit a behavior-preserving source simplification; test a real size reduction.'};\n  return {kind:'none',reason:'No observed failure or measured cost opportunity supports this objective.'};\n}\n",
  "improveStep/diagnose.nl": "---\nargs:\n  evidence: unknown[]\n  goal: string\nreturns: '{ hypotheses: { statement: string; citations: string[]; predictedChange: string }[] }'\n---\nReturn one concise, testable explanation of the observed failure relative to goal. Cite evidence identities. If no evidence supports a change, return {hypotheses: []}. Otherwise return {hypotheses: [{statement, citations, predictedChange}]}. These are hypotheses, not proven causes. Stop once you have one useful explanation.\n",
  "improveStep/experiment.ts": "import type {ExperimentResult,ExperimentFeedback,ImprovementPolicy,SearchState} from '../types';\nimport type {ExperimentFolder,ExperimentEvaluator} from './capabilities';\nimport {request} from './context';\nimport {inspect} from './feedback';\n/** One finite experiment. Hypothesis and source edits remain semantic decisions. */\nexport async function test(folder:ExperimentFolder,evaluator:ExperimentEvaluator,parentId:string,editor:unknown,policy:ImprovementPolicy,hypothesis:string,state?:SearchState):Promise<ExperimentResult> {\n  const parent=folder.at(parentId).branch();\n  const measured=await evaluator.evaluate(folder.at(parentId),{split:'validation',seed:policy.seed??0});\n  const feedback=await inspect(folder,evaluator,parentId,policy);\n  const rejected=(reason:string,feedback?:ExperimentFeedback):ExperimentResult=>({source:parentId,parent:parentId,accepted:false,reason,quality:measured.quality,sourceBytes:measured.sourceBytes,...(measured.modelCalls!==undefined?{modelCalls:measured.modelCalls}:{}),scores:measured.scores??[],...(feedback?{feedback}:{})});\n  if(feedback.opportunity.kind==='fixture')return rejected('fixture-error: '+feedback.evidence.filter(row=>row.failureKind==='fixture').map(row=>row.error??'Independent fixture failed.').join('\\n'));\n  const paths=parent.filePaths();\n  const sourceFiles=await Promise.all(paths.map(async path=>({path,text:await parent.readText(path)})));\n  const proposal=await parent.propose(editor,request(policy,hypothesis,feedback.evidence,sourceFiles,state?.history??[],state?.lastExperiment));\n  if(!proposal.diff.changes.length)return rejected('No supported hypothesis.');\n  const candidatePaths=proposal.folder.filePaths();\n  const candidateFiles=await Promise.all(candidatePaths.map(async path=>({path,text:await proposal.folder.readText(path)})));\n  const checked=await evaluator.check(proposal.folder);\n  if(!checked.valid){const reason='Compilation rejected: '+checked.diagnostics.join('\\n');return rejected(reason,{sourceFiles:candidateFiles,training:[],reason});}\n  const training=await evaluator.evaluate(proposal.folder,{split:'train',seed:policy.seed??0});\n  const candidate=await evaluator.evaluate(proposal.folder,{split:'validation',seed:policy.seed??0});\n  const objective=policy.objective??'quality';\n  const improvement=candidate.quality>measured.quality || candidate.quality===measured.quality && (\n    objective==='source-size' && candidate.sourceBytes<measured.sourceBytes ||\n    objective==='model-calls' && candidate.modelCalls!==undefined && measured.modelCalls!==undefined && candidate.modelCalls<measured.modelCalls);\n  const reason='Measured candidate: train quality '+training.quality+', validation quality '+candidate.quality+' vs '+measured.quality+', validation calls '+candidate.modelCalls+' vs '+measured.modelCalls+', bytes '+candidate.sourceBytes+' vs '+measured.sourceBytes+'.';\n  const diagnostics=evaluator.page(training.evidence).map(row=>'Train '+(row.caseId??'case')+': '+(row.passed?'passed':'failed; actual '+JSON.stringify(row.value)+', expected '+JSON.stringify(row.expected))+'; requests '+(row.modelCalls??'unknown')+(row.error?'; '+row.error:'')).map(text=>text.slice(0,700));\n  const candidateFeedback:ExperimentFeedback={diagnostics,sourceFiles:candidateFiles,training:evaluator.page(training.evidence),validation:{quality:candidate.quality,...(candidate.modelCalls!==undefined?{modelCalls:candidate.modelCalls}:{})},reason};\n  if(!training.gatesPassed||!candidate.gatesPassed||!improvement)return rejected(reason,candidateFeedback);\n  const installed=await parent.accept(proposal);\n  return {source:installed.digest,parent:parentId,accepted:true,reason:proposal.value.summary,quality:candidate.quality,sourceBytes:candidate.sourceBytes,...(candidate.modelCalls!==undefined?{modelCalls:candidate.modelCalls}:{}),scores:candidate.scores??[],feedback:candidateFeedback};\n}\n",
  "improveStep/feedback.ts": "import type {ImprovementPolicy,TrainingEvidence} from '../types';\nimport type {ExperimentFolder,ExperimentEvaluator} from './capabilities';\nimport {opportunity} from './context';\n/** Read measured training feedback, never validation answers. */\nexport async function inspect(folder:ExperimentFolder,evaluator:ExperimentEvaluator,parentId:string,policy:ImprovementPolicy):Promise<{evidence:TrainingEvidence[];opportunity:{kind:'fixture'|'quality'|'efficiency'|'source-size'|'none';reason:string}}> {\n  const training=await evaluator.evaluate(folder.at(parentId),{split:'train',seed:policy.seed??0});\n  const evidence=evaluator.page(training.evidence);\n  return {evidence,opportunity:opportunity(policy,evidence)};\n}\n",
  "improveStep/lifecycle.ts": "import type {ImprovementPolicy,SearchState} from '../types';\nimport {start} from './baseline';\nimport {advance} from './population';\nimport type {ExperimentFolder,ExperimentEvaluator,Snapshot} from './capabilities';\nimport {test} from './experiment';\nimport {frontierParent} from './parents';\ntype Folder=ExperimentFolder & {snapshot():Snapshot;select(source:unknown):Promise<void>};\n/** One finite experiment by construction: one semantic edit/test, exact selection. */\nexport async function step(folder:Folder,evaluator:ExperimentEvaluator,editor:unknown,state:SearchState,policy:ImprovementPolicy):Promise<SearchState> {\n  const source=folder.snapshot();\n  const validation=await evaluator.evaluate(source,{split:'validation',seed:policy.seed??0});\n  const current=state.iteration===0?start(state,validation):state;\n  const frame={current,baselineBytes:current.population[0].cost??validation.sourceBytes};\n  const parentId=policy.strategy==='gepa'?frontierParent(current.population,(policy.seed??0)+current.iteration+1):current.incumbent;\n  const experiment=await test(folder,evaluator,parentId,editor,policy,'',current);\n  return await advance(folder,evaluator,frame,experiment,policy);\n}\n",
  "improveStep/parents.ts": "import type {PopulationMember} from '../types';\n/** GEPA per-case frontier archive, with seeded sampling weighted by validation wins. */\nexport function frontierParent(population: PopulationMember[], seed: number): string {\n  const cases = [...new Set(population.flatMap(member => (member.scores ?? []).map(score => score.caseId)))].sort();\n  const winners: string[] = [];\n  for (const caseId of cases) {\n    const maximum = Math.max(...population.map(member => member.scores?.find(score => score.caseId === caseId)?.quality ?? -1));\n    for (const member of population) if (member.scores?.find(score => score.caseId === caseId)?.quality === maximum) winners.push(member.source);\n  }\n  const choices = winners.length ? winners.sort() : population.map(member => member.source).sort();\n  let random = seed >>> 0; random ^= random << 13; random ^= random >>> 17; random ^= random << 5;\n  return choices[(random >>> 0) % choices.length];\n}\n",
  "improveStep/population.ts": "import type {SearchState,PopulationMember,ExperimentFeedback} from '../types';\nimport {best,prune} from './selection';\ntype Experiment = {source:string;parent:string;accepted:boolean;selected:boolean;reason:string};\ntype MeasuredSource = {source:string;quality:number;sourceBytes?:number;scores?:{caseId:string;quality:number}[]};\n/** Exact state assembly. The caller makes every acceptance, selection and stopping decision. */\nexport function finishStep(state:SearchState,selected:MeasuredSource,population:PopulationMember[],experiment:Experiment,done:boolean,stopReason:string,lastExperiment?:ExperimentFeedback):SearchState {\n  if (!population.some(member=>member.source===selected.source && member.quality===selected.quality)) throw Error('selected source and quality must be in the population');\n  return {iteration:state.iteration+1,done,incumbent:selected.source,quality:selected.quality,population,\n    history:[...state.history,experiment],stopReason,...(lastExperiment?{lastExperiment}:{})};\n}\n\n/** Install a measured population member independently of accepting a draft. */\nexport async function advance(folder:{at(source:string):unknown;select(source:unknown):Promise<void>},evaluator:{evaluate(source:any,request:{split:'validation';seed:number}):Promise<MeasuredSource>},frame:import('../types').SearchFrame,experiment:import('../types').ExperimentResult,policy:import('../types').ImprovementPolicy):Promise<SearchState> {\n  const added=experiment.accepted?[...frame.current.population,{source:experiment.source,quality:experiment.quality,parent:experiment.parent,cost:experiment.sourceBytes,...(experiment.modelCalls!==undefined?{modelCalls:experiment.modelCalls}:{}),scores:experiment.scores}]:frame.current.population;\n  const selected=best(added,frame.current.incumbent,policy.objective??'quality');\n  const population=prune(added,selected,policy.maxPopulation);\n  await folder.select(folder.at(selected));\n  const measured=await evaluator.evaluate(folder.at(selected),{split:'validation',seed:policy.seed??0});\n  const satisfied=measured.quality===1 && (policy.objective??'quality')==='quality';\n  const exhaustedHypotheses=experiment.reason==='No supported hypothesis.';\n  const fixture=experiment.reason.startsWith('fixture-error:');\n  const limit=frame.current.iteration+1>=policy.maxExperiments;\n  return finishStep(frame.current,measured,population,{source:experiment.source,parent:experiment.parent,accepted:experiment.accepted,selected:experiment.accepted&&selected===experiment.source,reason:experiment.reason},fixture||satisfied||exhaustedHypotheses||limit,fixture?experiment.reason:satisfied?'Declared objective satisfied.':exhaustedHypotheses?'No further evidenced change.':limit?'Declared experiments completed.':'Continue with a distinct hypothesis.',experiment.feedback);\n}\n",
  "improveStep/rewriteProgram/bookkeeping.ts": "import type {RewriteResult} from '../../types';\n\n/** Derive the edit report from the folder, rather than asking the editor to copy paths. */\nexport async function finish(folder:{diff():Promise<{changes:{path:string}[]}>},summary:string,preserves:string[]):Promise<RewriteResult> {\n  const diff=await folder.diff();\n  return {summary,changed:diff.changes.map(change=>change.path),preserves};\n}\n",
  "improveStep/rewriteProgram.nl": "---\nkind: directory-reducer\nargs:\n  request: RewriteRequest\nreturns: RewriteResult\n---\nChoose one coherent, evidenced hypothesis and edit the program in folder to test it, using request.evidence and request.goal. request.hypothesis is a caller hint when supplied; diagnose the actual source and trace yourself. You are editing source, not answering the example task. request.history contains prior outcomes; request.lastExperiment contains the latest actual rejected or accepted source, training observations and compact diagnostics. Use failed actions or outputs to revise the next edit, without repeating a rejected hypothesis. Use the compact source/evidence card request.brief, reading it with eval only if its opening view is clipped. Once it supports a coherent edit, write and finish; there is no requirement to inspect every request field. Inspect only a specific clipped source or unresolved failure, never reprint the whole request or evidence repeatedly. request.sourceFiles already contains the existing paths and complete source text; use it directly rather than discovering or reading the same files again. request.allowedFiles may include new paths to create; do not try reading those before they exist. Inspect intermediate data with a final expression in eval, not a typed return. Do not call nl, folder.apply, folder.propose or an evaluator here: target execution and comparison belong to the caller.\n\nIn structural mode freely redesign the execution structure. The .nl interpreter can judge visible inputs directly; use exact code for counting and aggregation. Delegate a semantic batch only when a separate subproblem is useful. In instruction mode change prose only, preserving TypeScript, callable contracts and interpolation bindings. Edit only allowed files and preserve external behavior. Keep judgments semantic, including negation and sarcasm; never substitute keywords, known answers or holdout data. Ground service fields and enum meanings in evidence.serviceDeclarations, and explain which observed failure or unnecessary action the change addresses.\n\nUse write_file to create or replace a file, or edit_file to replace a span directly in the private folder. Eval folder.file(path).writeText(text) is also an ordinary option when computation is needed. Write each complete replacement once. After the edits, finish using the diff-derived helper; a sequential response may contain a file-tool action followed by the finishing eval. A failed action stops the batch. Remove contradictory and duplicated guidance. Finish with `return await bookkeeping.finish(folder, summary, preserves);` in eval with finish:true to compute and complete in one action. The helper derives changed paths from the actual diff; an unchanged file is not an edit. If no useful change is supported, leave the folder unchanged and use the same helper to report that honestly. Passing quality permits further measured cost simplification; an accepted gain is a new starting point. Without finish:true a final expression only inspects; with finish:true its fresh typed value completes the declared RewriteResult. Do not return an inspection record or the example answer as RewriteResult.\n",
  "improveStep/selection.ts": "import type {PopulationMember} from '../types';\n/** Exact, baseline-preserving incumbent selection. */\nexport function best(population: PopulationMember[], incumbent: string, objective: 'quality'|'source-size'|'model-calls'='quality'): string {\n  const maximum = Math.max(...population.map(member => member.quality));\n  let eligible = population.filter(member => member.quality === maximum);\n  if(objective==='source-size'){const minimum=Math.min(...eligible.map(member=>member.cost??Infinity));eligible=eligible.filter(member=>(member.cost??Infinity)===minimum);}\n  if(objective==='model-calls'){const minimum=Math.min(...eligible.map(member=>member.modelCalls??Infinity));eligible=eligible.filter(member=>(member.modelCalls??Infinity)===minimum);}\n  if(eligible.some(member=>member.source===incumbent))return incumbent;\n  return eligible.map(member=>member.source).sort()[0];\n}\nexport function prune(population: PopulationMember[], selected: string, limit: number): PopulationMember[] {\n  if(!Number.isSafeInteger(limit)||limit<2)throw Error('population limit must retain baseline and incumbent');\n  const unique=population.filter((member,index)=>population.findIndex(other=>other.source===member.source)===index);\n  const protectedMembers=unique.filter(member=>member.source===selected||member.parent==='');\n  const frontier=new Set<string>();\n  for(const caseId of [...new Set(unique.flatMap(member=>(member.scores??[]).map(score=>score.caseId)))]){\n    const maximum=Math.max(...unique.map(member=>member.scores?.find(score=>score.caseId===caseId)?.quality??-1));\n    for(const member of unique)if(member.scores?.find(score=>score.caseId===caseId)?.quality===maximum)frontier.add(member.source);\n  }\n  return [...protectedMembers,...unique.filter(member=>!protectedMembers.includes(member)).sort((a,b)=>Number(frontier.has(b.source))-Number(frontier.has(a.source))||b.quality-a.quality||a.source.localeCompare(b.source))].slice(0,limit);\n}\n",
  "improveStep.nl": "---\nkind: directory-reducer\nargs:\n  state: SearchState\n  policy: ImprovementPolicy\nreturns: SearchState\n---\nImprove this source through one evidenced experiment. Return `await lifecycle.step(folder, evaluator, rewriteProgram, state, policy)` in eval with finish:true. Exact authored helpers supply measured source and training feedback to one directory reducer that diagnoses and edits the private folder, then check, measure and select the result. Return a rejected or unchanged experiment honestly. The outer folder.iterateOn owns repetition; do not run additional experiments inside this step or invent scores.\n",
  "reducers/clarifyInstructions.nl": "---\nkind: directory-reducer\nargs:\n  request: TransformationRequest\nreturns: TransformationExplanation\n---\nRewrite vague and contradictory instructions into clear executable semantic rules, using concrete input roles and explicit negative or missing-information outcomes. Retain behavior and contracts.\nRead the real source and request before editing. Make actual file changes in folder and return changed paths, rationale, and preserved rules. Evaluation and acceptance belong to the caller.\n\nStay within request.allowedFiles. Preserve request.preserves when supplied and the declared entrypoint. Use request.evidence and any supplied request.checks to test the hypothesis; expected held-out answers are unavailable. Return the actual changed paths, not an intended patch.\n",
  "reducers/extractHelper.nl": "---\nkind: directory-reducer\nargs:\n  request: TransformationRequest\nreturns: TransformationExplanation\n---\nExtract a repeated semantic judgment into a typed named natural-language helper with a companion folder. Retain external behavior and finite control flow.\nRead the real source and request before editing. Make actual file changes in folder and return changed paths, rationale, and preserved rules. Evaluation and acceptance belong to the caller.\n\nStay within request.allowedFiles. Preserve request.preserves when supplied and the declared entrypoint. Use request.evidence and any supplied request.checks to test the hypothesis; expected held-out answers are unavailable. Return the actual changed paths, not an intended patch.\n",
  "reducers/implementProgram.nl": "---\nkind: directory-reducer\nargs:\n  request: TransformationRequest\nreturns: TransformationExplanation\n---\nImplement the requested application in native natlang: named semantic functions and directory reducers, typed contracts, finite exact helpers and folder.iterateOn for bounded improvement. Preserve the pinned external entry.\nRead the real source and request before editing. Make actual file changes in folder and return changed paths, rationale, and preserved rules. Evaluation and acceptance belong to the caller.\n\nStay within request.allowedFiles. Preserve request.preserves when supplied and the declared entrypoint. Use request.evidence and any supplied request.checks to test the hypothesis; expected held-out answers are unavailable. Return the actual changed paths, not an intended patch.\n",
  "reducers/removeDuplicatedGuidance.nl": "---\nkind: directory-reducer\nargs:\n  request: TransformationRequest\nreturns: TransformationExplanation\n---\nRemove duplicated or contradictory instructions. Keep each rule in the narrowest appropriate scope; retain externally required behavior.\nRead the real source and request before editing. Make actual file changes in folder and return changed paths, rationale, and preserved rules. Evaluation and acceptance belong to the caller.\n\nStay within request.allowedFiles. Preserve request.preserves when supplied and the declared entrypoint. Use request.evidence and any supplied request.checks to test the hypothesis; expected held-out answers are unavailable. Return the actual changed paths, not an intended patch.\n",
  "reducers/repairProgram.nl": "---\nkind: directory-reducer\nargs:\n  request: TransformationRequest\nreturns: TransformationExplanation\n---\nRepair a program using supplied failure evidence. Change semantics or structure as justified, preserve regressions and the external entry, and explain the hypothesis tested.\nRead the real source and request before editing. Make actual file changes in folder and return changed paths, rationale, and preserved rules. Evaluation and acceptance belong to the caller.\n\nStay within request.allowedFiles. Preserve request.preserves when supplied and the declared entrypoint. Use request.evidence and any supplied request.checks to test the hypothesis; expected held-out answers are unavailable. Return the actual changed paths, not an intended patch.\n",
  "reducers/simplifyProgram.nl": "---\nkind: directory-reducer\nargs:\n  request: TransformationRequest\nreturns: TransformationExplanation\n---\nSimplify the native semantic program. Remove unnecessary machinery, make semantic decisions explicit in natlang, retain finite execution and external behavior.\nRead the real source and request before editing. Make actual file changes in folder and return changed paths, rationale, and preserved rules. Evaluation and acceptance belong to the caller.\n\nStay within request.allowedFiles. Preserve request.preserves when supplied and the declared entrypoint. Use request.evidence and any supplied request.checks to test the hypothesis; expected held-out answers are unavailable. Return the actual changed paths, not an intended patch.\n",
  "reducers/specializeForModel.nl": "---\nkind: directory-reducer\nargs:\n  request: TransformationRequest\nreturns: TransformationExplanation\n---\nSimplify instructions and API usage for an underpowered coding model using observed failures. Prefer explicit folder.propose, evaluator.check/evaluate, folder.accept and folder.select. Do not memorize answers.\nRead the real source and request before editing. Make actual file changes in folder and return changed paths, rationale, and preserved rules. Evaluation and acceptance belong to the caller.\n\nStay within request.allowedFiles. Preserve request.preserves when supplied and the declared entrypoint. Use request.evidence and any supplied request.checks to test the hypothesis; expected held-out answers are unavailable. Return the actual changed paths, not an intended patch.\n",
  "reducers/suggestCounterexamples.nl": "---\nargs:\n  request: CounterexampleRequest\nreturns: CounterexampleSuggestions\n---\nSuggest concrete deployment inputs that distinguish a plausible faulty implementation from the requested behavior. Use the public contract and training failure evidence in request. Return at most request.maxSuggestions argument lists with a short reason. Do not invent expected results: the independent author-supplied oracle will score these inputs. Do not request validation or test cases. Return inputs and reason; no source edits or evaluation authority belong to this reducer.\n",
  "reducers/types.ts": "export type TransformationRequest = {goal:string;allowedFiles:string[];preserves?:string[];changes?:string[];checks?:string[];evidence:unknown[]};\nexport type TransformationExplanation = {summary:string;changed:string[];preserves:string[]};\nexport type CounterexampleRequest={goal:string;contract:string;evidence:string;maxSuggestions:number};\nexport type CounterexampleSuggestions={inputs:unknown[][];reason:string};\n",
  "types.ts": "export type PopulationMember = {source:string;quality:number;parent:string;cost?:number;modelCalls?:number;scores?:{caseId:string;quality:number}[]};\nexport type ExperimentOutcome = { source: string; parent: string; accepted: boolean; selected: boolean; reason: string };\nexport type SearchState = { iteration: number; done: boolean; incumbent: string; quality: number; population: PopulationMember[]; history: ExperimentOutcome[]; stopReason: string; lastExperiment?:unknown };\nexport type ImprovementPolicy = {seed?:number; maxExperiments: number; mode: 'instruction' | 'structural'; strategy: 'gepa' | 'adaptive'; objective?:'quality'|'source-size'|'model-calls'; goal: string; outerLesson?:string; allowedFiles: string[]; maxPopulation: number };\nexport type SourceFile = {path:string;text:string};\nexport type RewriteRequest = {brief:string; history?:ExperimentOutcome[]; lastExperiment?:unknown; objective?:'quality'|'source-size'|'model-calls'; goal: string; mode: string; hypothesis: string; sourceFiles:SourceFile[]; evidence: unknown[]; allowedFiles: string[]; preserves?:string[]; changes?:string[]; checks?:string[] };\nexport type RewriteResult = { summary: string; changed: string[]; preserves: string[] };\n\nexport type ComponentValue = {kind:'program.guidance';text:string} | {kind:'lambda.instructions';template:{segments:string[];slotIds:string[]}};\nexport type Candidate = Record<string,ComponentValue>;\nexport type ComponentRewriteRequest = {keys:string[];components:unknown[];feedback:unknown};\nexport type ComponentLoopState = {iteration:number;incumbent:string;done:boolean;stopReason:string};\nexport type CounterexampleState={round:number;done:boolean;suite:string;remainingChecks:number;quality:number;reason:string};\nexport type SearchFrame = {current:SearchState;baselineBytes:number};\nexport type ExperimentResult = {source:string;parent:string;accepted:boolean;reason:string;quality:number;sourceBytes:number;modelCalls?:number;scores:{caseId:string;quality:number}[];feedback?:ExperimentFeedback};\n\n\nexport type TrainingEvidence={caseId?:string;quality?:number;gates?:Record<string,boolean>;evidence?:string;modelTraceTruncated?:boolean;expectedFiles?:Record<string,string>;passed:boolean;modelCalls?:number;failureKind?:string;error?:string;value?:unknown;expected?:unknown;args?:unknown[];modelTrace?:{calls:unknown;observation:string}[];serviceDeclarations?:Record<string,string>};\n\nexport type ExperimentFeedback={diagnostics?:string[];sourceFiles:SourceFile[];training:TrainingEvidence[];validation?:{quality:number;modelCalls?:number};reason:string};\n"
} as const;
